import{az as e,P as t,Q as l,aQ as r}from"./chunks/framework.oHSDCGnP.js";import"./chunks/theme.SRuXo2Mz.js";const V=JSON.parse('{"title":"设计思想","description":"","frontmatter":{},"headers":[],"relativePath":"框架/vue/vue/设计思想.md","filePath":"框架/vue/vue/设计思想.md","lastUpdated":1785249401000}'),i={name:"框架/vue/vue/设计思想.md"};function n(o,a,p,c,d,u){return t(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="设计思想" tabindex="-1">设计思想 <a class="header-anchor" href="#设计思想" aria-label="Permalink to “设计思想”">​</a></h1><h2 id="mvc-和-mvvm-双向数据绑定" tabindex="-1">MVC 和 MVVM（双向数据绑定） <a class="header-anchor" href="#mvc-和-mvvm-双向数据绑定" aria-label="Permalink to “MVC 和 MVVM（双向数据绑定）”">​</a></h2><p>MVVM 是 Model-View-ViewModel 的简写。它本质上就是 MVC 的改进版。MVVM 就是将其中的 View 的状态和行为抽象化，让我们将视图 UI 和业务逻辑分开。通过数据驱动（VM）视图（View）。当数据变化时，自动去刷新页面 DOM，这使得我们能从繁琐的 DOM 操作中解放出来，从而专心地去处理业务逻辑。</p><h2 id="单向数据流" tabindex="-1">单向数据流 <a class="header-anchor" href="#单向数据流" aria-label="Permalink to “单向数据流”">​</a></h2><p>组件之间进行数据传递，无法直接将传递进来的数据进行修改，而是通过父组件提供的方法进行修改，达到显式行为，让状态修改有迹可寻。</p><h2 id="为什么要使用虚拟-dom" tabindex="-1">为什么要使用虚拟 DOM <a class="header-anchor" href="#为什么要使用虚拟-dom" aria-label="Permalink to “为什么要使用虚拟 DOM”">​</a></h2><p>性能提升。虚拟 DOM 通过 diff 算法最小化 DOM 操作，减少直接操作真实 DOM 带来的性能开销。</p><h2 id="vue、react、angular-哪个更好" tabindex="-1">Vue、React、Angular 哪个更好？ <a class="header-anchor" href="#vue、react、angular-哪个更好" aria-label="Permalink to “Vue、React、Angular 哪个更好？”">​</a></h2><ul><li><p>与其说哪个更好，主要是看社区更发达为主要优点之一。</p></li><li><p>Vue 集成了 React 和 Angular 的优点，通过 Vue 核心去对比三大框架：</p><ul><li>集成了 Angular 的哪些优点</li><li>相比之下不如 Angular 的地方</li><li>集成了 React 的哪些优点</li><li>相比之下不如 React 的地方</li></ul></li><li><p>Vue 和 React 都可以完成相同的事情。两者都是 JS，但是 React 偏向于底层 JS，而 Vue 框架内提供了大量的 API，偏向于 jQuery。但是 Vue3 新推出了 Composition API（组合式开发）更加融合了 Vue 集合了 Angular、React 两者的优点，对新接触框架的人更友好。</p></li><li><p>React 不算是真正意义上的框架，而是一种开发范式。它的核心思想非常简单：</p><blockquote><p>界面/视图就是数据结构的可视化表达</p><p><code>UI = f(data)</code></p><p>而界面/视图由组件组合而来</p><p><code>UI = f1(data) + f2(data) + f3(data) + ...</code></p><p>That&#39;s all.</p></blockquote><p>三大框架整体的核心思想都是源于数据驱动（MVVM）。</p></li></ul><p>参考文章：<a href="https://juejin.cn/post/6850037277675454478#heading-1" target="_blank" rel="noreferrer">https://juejin.cn/post/6850037277675454478#heading-1</a></p>',10)])])}const _=e(i,[["render",n]]);export{V as __pageData,_ as default};
